PYTHONPATH=/opt/tools python -c 'import numpy as np; from PIL import Image; im=np.array(Image.open("/tmp/obs_head_camera.png")); dep=np.load("/tmp/depth_head_camera.npy")[0].astype(float)/1000; red=(im[:,:,0]>100)&(im[:,:,0]>im[:,:,1]*1.25)&(im[:,:,0]>im[:,:,2]*1.25); dark=(im[:,:,0]<55)&(im[:,:,1]<55)&(im[:,:,2]<55); print("red count",red.sum(),"bbox",np.where(red)[1].min(),np.where(red)[0].min(),np.where(red)[1].max(),np.where(red)[0].max()); print("depth red",np.nanmedian(dep[red])); print("dark bbox count",dark.sum(),"bottle candidates"); print([(u,v,im[v,u].tolist(),dep[v,u]) for u,v in [(75,80),(85,95),(95,110),(105,120),(115,130),(120,140)]]); K=np.array([[358.642,0,160],[0,358.642,120],[0,0,1]]); W=np.eye(4); E=np.array([[1,0,0,.032],[0,-.8,-.6,.45],[0,.6,-.8,1.35],[0,0,0,1]],float); # world->cv per spec; note x translation is +.032? printed extrinsic has +.032, yes xcam=x+.032
for name,m in [("red",red)]:
 ids=np.argwhere(m & (dep>.4)&(dep<1.2)); pts=[]
 for v,u in ids[::max(1,len(ids)//1000)]:
  z=dep[v,u]; c=np.array([(u-160)*z/358.642,(v-120)*z/358.642,z,1]); pts.append(np.linalg.inv(E)@c)
 P=np.array(pts); print("red world q",np.quantile(P[:,:3],[.1,.5,.9],axis=0), "mean",np.mean(P[:,:3],axis=0))'

python -c 'import numpy as np; from PIL import Image; im=np.array(Image.open("/tmp/afterlift_head_camera.png")); dep=np.load("/tmp/depth_afterlift_head_camera.npy")[0].astype(float)/1000; f=358.6421814; E=np.array([[1,0,0,.032],[0,-.8,-.6,.45],[0,.6,-.8,1.35],[0,0,0,1]],float); T=np.linalg.inv(E); O=T[:3,3]; vv,uu=np.indices(dep.shape); rays=np.stack([(uu-160)/f,(vv-120)/f,np.ones_like(dep)],-1)@T[:3,:3].T; w=O+rays*dep[:,:,None]; roi=(uu<65)&(vv>50)&(vv<180)&(w[:,:,2]>.745)&(w[:,:,2]<.84); red=(im[:,:,0]>100)&(im[:,:,0]>im[:,:,1]*1.25)&(im[:,:,0]>im[:,:,2]*1.25)&roi; dark=(im.max(2)<85)&roi; 
for name,m in [("red",red),("dark",dark)]:
 P=w[m]; print(name,len(P),"uv",((uu[m].min(),vv[m].min(),uu[m].max(),vv[m].max()) if len(P) else None));
 if len(P):
  xy=P[:,:2]; ev,V=np.linalg.eigh(np.cov(xy.T)); print("xy q",np.quantile(xy,[.1,.5,.9],axis=0),"axis",V[:,-1],"z",np.quantile(P[:,2],[.1,.5,.9]));'

